// 02 — Read Message & Classify Intent
// Normalise the raw Telegram Trigger output into a single "envelope" that every downstream node reads from.

const item = $input.first().json;
const msg = item.message ?? {};
const chat = msg.chat ?? {};
const from = msg.from ?? {};

const rawText = typeof msg.text === 'string' ? msg.text.trim() : '';

// V1 only handles two commands: /start and /help.
// Both are plain-text replies — no Apify call, no AI call, zero cost.
// When V2 adds /hooks /ideas /script, just recognise a few more prefixes here
// and map route to the matching analysisMode; downstream code stays unchanged.
let route = 'process';
let analysisMode = 'full_analysis';
let commandName = null;

const lower = rawText.toLowerCase();
const isCommand = (name) => lower === `/${name}` || lower.startsWith(`/${name}@`);

if (isCommand('start')) {
  route = 'help';
  commandName = 'start';
} else if (isCommand('help')) {
  route = 'help';
  commandName = 'help';
}

return [
  {
    json: {
      // Always store as strings: Telegram IDs can exceed 32 bits, and group/channel IDs are negative.
      // Storing them as numbers truncates them or drops the minus sign, and Telegram replies "chat not found".
      chatId: chat.id === undefined || chat.id === null ? '' : String(chat.id),
      userId: from.id === undefined || from.id === null ? '' : String(from.id),
      messageId: msg.message_id ?? null,
      chatType: chat.type ?? 'private',
      rawText,
      hasText: rawText.length > 0,
      route,
      commandName,
      analysisMode,
      forceRefresh: false, // the V2 /fresh command will set this to true
      receivedAt: new Date().toISOString(),
    },
  },
];

// 04 — Extract & Validate Reel URL
// Pull an Instagram link out of arbitrary text → normalise → decide whether it is supported.
// This is the "first gate": if unsupported, stop here and never call the paid Actor.

const d = $input.first().json;
const text = d.rawText || '';

// ⚠️⚠️ Never use `new URL()` / `URLSearchParams` / `fetch` / `setTimeout` here!
// The n8n Code node runs in a sandbox and **does not have these Node / browser globals**.
// Measured on local n8n 2.42: `typeof URL === 'undefined'`, and any call throws
// `ReferenceError: URL is not defined`.
// The nastier part: with an outer try/catch this error is silently swallowed,
// showing up as "the user sent a valid link but the bot replies with the help text" — hard to track down.
// So this parses host and path with plain regex, depending on no global objects.

// Single pass: group 1 is the domain, group 2 is the path (including the leading /).
// The trailing character class stops at whitespace, quotes, or ASCII/CJK brackets.
const IG_RE = /https?:\/\/([^\s/<>"'）)】]+)(\/[^\s<>"'）)】]*)/gi;

// The official README states only these three hosts are supported
const SUPPORTED_HOSTS = ['instagram.com', 'www.instagram.com', 'm.instagram.com'];

// Supported path shapes:
//   /reel/<shortcode>            standard Reel
//   /reels/<shortcode>           plural form
//   /p/<shortcode>               post (transcribable if it is a video; the Actor returns media_not_found for image posts)
//   /<username>/reel/<shortcode> share form with username
//   /<username>/p/<shortcode>
const PATH_RE = /^\/(?:[A-Za-z0-9._]+\/)?(reel|reels|p)\/([A-Za-z0-9_-]+)$/;

let normalizedUrl = null;
let reelId = null;
let postKind = null;
let failureCode = null;
let unsupportedReason = null;

let candidateCount = 0;
const accepted = [];
let sawNonVideoInstagramLink = false;

let m;
while ((m = IG_RE.exec(text)) !== null) {
  candidateCount++;

  const host = m[1].toLowerCase();
  if (!SUPPORTED_HOSTS.includes(host)) continue; // looks like it but not an instagram domain — ignore it

  // Strip the ?query string and #fragment, then any trailing slash
  const path = (m[2] || '').split(/[?#]/)[0].replace(/\/+$/, '');
  const pm = path.match(PATH_RE);

  if (!pm) {
    sawNonVideoInstagramLink = true;
    // Also figure out which kind of unsupported, so the user gets a more precise hint
    if (/^\/(stories|tv|reels\/tv)\//i.test(path)) unsupportedReason = 'story';
    else if (/^\/explore/i.test(path)) unsupportedReason = 'explore';
    else if (/^\/(accounts|direct|about)\b/i.test(path)) unsupportedReason = 'other';
    else unsupportedReason = 'profile';
    continue;
  }

  const kind = pm[1] === 'p' ? 'post' : 'reel';
  accepted.push({ kind, id: pm[2], url: `https://www.instagram.com/${pm[1]}/${pm[2]}/` });
}

if (candidateCount === 0) {
  failureCode = 'NO_URL';
} else if (accepted.length === 0) {
  failureCode = sawNonVideoInstagramLink ? 'UNSUPPORTED_URL' : 'NO_URL';
} else {
  normalizedUrl = accepted[0].url;
  reelId = accepted[0].id;
  postKind = accepted[0].kind;
}

return [
  {
    json: {
      ...d,
      urlValid: normalizedUrl !== null,
      normalizedUrl,
      reelId,
      postKind,
      failureCode,
      unsupportedReason,
      // Only take the first link; when a message has several, the user is told later
      extraUrlCount: Math.max(0, candidateCount - 1),
      cacheKey: reelId ? `reel:${reelId}` : null,
    },
  },
];

// 06 — Check Recent Cache
// Second gate. If the same Reel is sent again shortly after, reuse the previous result and skip paying for the Actor.
//
// Uses n8n's built-in static data ($getWorkflowStaticData):
//   - zero config, zero credentials, works automatically with the template
//   - even if it fails to work in some environments, the worst case is just "cache miss, run again",
//     invisible to the user and never breaks functionality. This is the main reason for choosing it over a Data Table
//     (a Data Table's schema is not exported with the workflow, so importing the public template errors out).

// ===== Tunable parameters (edit here only) =====
const CACHE_TTL_MS = 24 * 60 * 60 * 1000; // expires after 24 hours so the user can regenerate
const MAX_ENTRIES = 15; // max entries kept; exceeding this evicts oldest first
const MAX_BYTES = 40000; // overall size cap, an extra fallback
// ===================================

const d = $input.first().json;
const store = $getWorkflowStaticData('global');
if (!store.reelCache || typeof store.reelCache !== 'object') store.reelCache = {};

let cacheHit = false;
let cached = null;
let cacheAgeMs = null;

if (!d.forceRefresh && d.cacheKey && store.reelCache[d.cacheKey]) {
  const entry = store.reelCache[d.cacheKey];
  const age = Date.now() - Number(entry.createdAt || 0);
  if (age >= 0 && age < CACHE_TTL_MS) {
    cacheHit = true;
    cached = entry;
    cacheAgeMs = age;
  } else {
    delete store.reelCache[d.cacheKey]; // clean up expired entries so they do not pile up
  }
}

return [
  {
    json: {
      ...d,
      cacheHit,
      cached,
      cacheAgeMs,
    },
  },
];

// 12 — Validate Transcript
// Third gate. Read the dataset items returned by the Actor and decide whether this transcript is usable.
//
// All field names here come from real runs on 2026-10-12 (see research/fixture_real_output.json
// and research/fixture_failure_cases.json), not guessed from the docs.

// ===== Tunable parameters =====
const MIN_TRANSCRIPT_CHARS = 8; // below this length there is essentially nothing transcribed
// ===================

const upstream = $('04 — Extract & Validate Reel URL').first().json;
const items = $input.all().map((i) => i.json);
const rec = items[0] ?? {};

// Real samples confirm: when fields are missing, the content / author / engagement objects
// may have a null field, or the whole object may be absent. So always use optional chaining + fallback.
const tr = rec.transcript && typeof rec.transcript === 'object' ? rec.transcript : null;
const transcriptText = tr && typeof tr.text === 'string' ? tr.text.trim() : '';

const status = typeof rec.status === 'string' ? rec.status : 'error';
const success = rec.success === true;
const errCode = rec.error?.code ?? null;
const errRetryable = rec.error?.retryable === true;

// Actor status → our internal failureCode
function mapStatus(st) {
  switch (st) {
    case 'invalid_url':
      return 'UNSUPPORTED_URL';
    case 'login_required':
      return 'LOGIN_REQUIRED';
    case 'private_content':
      return 'PRIVATE_CONTENT';
    case 'media_not_found':
      return 'MEDIA_NOT_FOUND';
    case 'no_speech':
      return 'NO_SPEECH';
    case 'transcription_failed':
      return 'TRANSCRIPTION_FAILED';
    default:
      return 'ACTOR_ERROR';
  }
}

let transcriptUsable = false;
let failureCode = null;

if (items.length === 0) {
  failureCode = 'EMPTY_RESULT';
} else if (!success) {
  failureCode = mapStatus(status);
} else if (!tr) {
  failureCode = 'EMPTY_TRANSCRIPT';
} else if (transcriptText.length < MIN_TRANSCRIPT_CHARS) {
  failureCode = 'TRANSCRIPT_TOO_SHORT';
} else {
  transcriptUsable = true;
}

return [
  {
    json: {
      ...upstream,
      actorStatus: status,
      actorErrorCode: errCode,
      // Only MEDIA_TEMPORARILY_UNAVAILABLE with retryable=true is worth asking the user to retry
      // (this comes from the official README; that state was not reproduced in this round)
      retryable: errRetryable,
      transcriptUsable,
      failureCode,

      // ---- the fields below are for the AI ----
      transcriptText,
      transcriptChars: transcriptText.length,
      language: tr?.language ?? null,
      characterCount: tr?.characterCount ?? null,
      segmentCount: Array.isArray(tr?.segments) ? tr.segments.length : 0,
      firstSegment: Array.isArray(tr?.segments) && tr.segments.length ? tr.segments[0] : null,

      creatorHandle: rec.author?.username ?? null,
      creatorName: rec.author?.displayName ?? null,
      creatorVerified: rec.author?.verified === true,
      caption: typeof rec.content?.caption === 'string' ? rec.content.caption : '',
      durationSeconds: Number.isFinite(rec.content?.durationSeconds) ? rec.content.durationSeconds : null,
      likeCount: rec.engagement?.likeCount ?? null,
      commentCount: rec.engagement?.commentCount ?? null,
    },
  },
];

// 14 — Build AI Prompt
// Assemble the prompt by analysis_mode.
// V1 has only the full_analysis branch, but the structure already leaves room:
// adding /hooks /ideas /script later needs one more case here, with zero changes to the AI node or downstream code.

const MAX_TRANSCRIPT_CHARS = 12000; // roughly 3k tokens; a Reel almost never hits this cap
const THIN_TRANSCRIPT_CHARS = 120; // below this length, remind the model not to make things up

const d = $input.first().json;
const mode = d.analysisMode || 'full_analysis';

// ---- The fixed part (the originality rule matters most, so it is fenced off to make the model take it seriously) ----
const CORE = `You are a content strategist who reverse-engineers short-form video.

You will receive the transcript of an Instagram Reel, plus basic metadata.

Analyse it as CONTENT STRATEGY RESEARCH MATERIAL, not as something to summarise.

--- ORIGINALITY RULE (non-negotiable) ---
Learn from the structure, topic, persuasion technique and content angle.
Do NOT imitate or reproduce the creator's wording.
Do NOT paraphrase the original script by swapping a few words.
Every hook, idea and script you produce must be something you could publish
under your own name without it reading like a copy of the source.
--- END ORIGINALITY RULE ---

Ground rules:
- Never invent quotes, numbers, claims or outcomes that are not in the transcript.
- If the transcript is thin, ambiguous, or has no clear hook, say so honestly.
  Use the literal string NONE for a field that genuinely does not exist.
- Write your analysis in the same language as the transcript.
- Put the transcript's language code in the "language" field.`;

const FULL_ANALYSIS = `

Produce a complete content-strategy breakdown:
- What the Reel is about
- The opening hook, and what type of hook it is
- Core topic and content angle
- Target audience, the problem or desire it speaks to
- Key message and call to action
- The dominant emotional trigger
- The step-by-step structure
- Why it works (explain the mechanism, do not flatter the creator)
- 3 original hooks for the same underlying idea
- 3 adjacent content ideas that extend the same insight
- 1 complete original Reel script (hook / body / cta) built on the same underlying idea`;

// ---- mode lookup table: add V2 entries here ----
const MODE_BLOCKS = {
  full_analysis: FULL_ANALYSIS,
  // hooks_only:  `...`,
  // ideas_only:  `...`,
  // script_only: `...`,
};

// ---- Assemble the user message ----
let transcript = d.transcriptText || '';
let truncated = false;
if (transcript.length > MAX_TRANSCRIPT_CHARS) {
  transcript = transcript.slice(0, MAX_TRANSCRIPT_CHARS);
  truncated = true;
}

const meta = [
  `Creator: ${d.creatorHandle || 'unknown'}${d.creatorVerified ? ' (verified)' : ''}`,
  `Video length: ${d.durationSeconds ?? 'unknown'} seconds`,
  `Transcript length: ${d.transcriptChars} characters`,
  d.language ? `Detected language: ${d.language}` : null,
  d.caption ? `Caption: ${d.caption.slice(0, 500)}` : null,
].filter(Boolean);

const thinNotice =
  d.transcriptChars < THIN_TRANSCRIPT_CHARS
    ? '\n\nNOTE: this transcript is unusually short. If it does not contain enough information to analyse, say so explicitly rather than filling the fields with guesses.'
    : '';

const userPrompt = `--- METADATA ---
${meta.join('\n')}

--- TRANSCRIPT${truncated ? ' (truncated for analysis)' : ''} ---
"""
${transcript}
"""${thinNotice}`;

return [
  {
    json: {
      ...d,
      analysisMode: mode,
      systemPrompt: CORE + (MODE_BLOCKS[mode] ?? FULL_ANALYSIS),
      userPrompt,
      // The Basic LLM Chain input box accepts only a single text block, with no separate system message field.
      // Concatenate the two so it runs on any n8n version without relying on a version-specific hidden parameter.
      prompt: CORE + (MODE_BLOCKS[mode] ?? FULL_ANALYSIS) + '\n\n=== REEL DATA ===\n' + userPrompt,
      transcriptTruncated: truncated,
    },
  },
];

// 17 — Format Creator Insights
// Every path (success / cache hit / various failures) converges on this one node, which outputs a chunked array of text,
// sent one by one by 18 — Reply In Telegram. That needs only one send node and avoids
// the situation where some errors get a reply and others are silent.

// ===== Tunable parameters =====
const CHUNK_LIMIT = 3800;        // Telegram's per-message limit is 4096, leaving headroom
const SEND_TRANSCRIPT = false;    // set to true to append the raw transcript after the analysis
const MAX_TRANSCRIPT_CHARS = 3000; // transcript cap when appending it
// ===================

const base = $('02 — Read Message & Classify Intent').first().json;

// ⚠️ With an output parser attached, n8n 2.x's Basic LLM Chain **wraps the parsed result in an output field**,
//    so the node output is { output: { summary: ..., ... } } rather than flat at the top level.
//    Measured: local n8n 2.42.7 + deepseek-flash has exactly this shape.
//    Both shapes are handled here — otherwise you get "the AI produced a full result but downstream reads no field at all",
//    and this node can only reply "analysis failed", which looks like a broken model but is really a wrong read.
const rawIn = $input.first().json;
const isWrapped =
  rawIn && rawIn.output && typeof rawIn.output === 'object' && !Array.isArray(rawIn.output);
const inData = isWrapped ? { ...rawIn.output, ...rawIn } : rawIn;

// Strip the output wrapper before caching: the content is fully duplicated and wastes space (the cache caps at 40KB).
function stripOutput(o) {
  const copy = { ...o };
  delete copy.output;
  return copy;
}

// Metadata (creator, duration, language, original URL) comes from node 12.
// The AI node replaces $json with the structured analysis, so this must fetch from upstream and cannot use $json directly.
// On a cache hit or early rejection node 12 did not run and throws, so fall back to $json (those fields are unused on that path).
let meta = inData;
try {
  meta = $('12 — Validate Transcript').first().json;
} catch {
  meta = inData;
}

// Remove angle brackets, which would blow up the Telegram HTML parser.
// Normal scripts contain almost no angle brackets, so removing them loses nothing, but it blocks the "HTML parse mode left on" trap.
// Note: do not escape & — with parse mode off it should display as-is; escaping it would render as &amp;
function stripBrackets(s) {
  return String(s ?? '').replace(/[<>]/g, '');
}
function clean(s) {
  return stripBrackets(s).trim();
}
function none(v) {
  const t = clean(v);
  return !t || t.toUpperCase() === 'NONE' ? null : t;
}
function compactNum(n) {
  if (typeof n !== 'number' || !Number.isFinite(n)) return null;
  if (n >= 1e6) return (n / 1e6).toFixed(1).replace(/\.0$/, '') + 'M';
  if (n >= 1e3) return (n / 1e3).toFixed(1).replace(/\.0$/, '') + 'K';
  return String(n);
}

// ---------- 1. Help text (/start and /help, zero cost) ----------
const HELP_TEXT = [
  'Hi. Send me an Instagram Reel and I will break it down.',
  '',
  'What you get back:',
  '- What it is about, and the opening hook',
  '- Who it targets, what it triggers, and why it works',
  '- 3 original hooks and 3 adjacent content ideas',
  '- 1 complete original Reel script based on the same idea',
  '',
  'How to use it:',
  '1. Open a Reel on Instagram',
  '2. Tap the share button and choose "Copy Link"',
  '3. Paste the link straight into this chat',
  '',
  'You can paste it on its own or with some words around it — both work.',
  'I only handle Reels and video posts, not profiles or Stories.',
].join('\n');

// ---------- 2. Failure messages ----------
// Principle: speak plainly — say what happened and what the user should do.
// Never surface raw API errors, Actor names, tokens, or provider names.
const ERROR_MESSAGES = {
  NO_URL: [
    'Send me an Instagram Reel URL and I will turn it into a transcript, content breakdown, and new content ideas.',
    '',
    'Just tap Copy Link on the Reel and paste it here — extra words around the link are fine.',
  ].join('\n'),

  UNSUPPORTED_URL_PROFILE: [
    'That link is an Instagram profile, not a video.',
    '',
    'Send me a Reel or video post instead. It looks like this:',
    'https://www.instagram.com/reel/XXXXXXXXXXX/',
  ].join('\n'),

  UNSUPPORTED_URL_STORY: [
    'Instagram Stories cannot be transcribed.',
    '',
    'Send me a Reel or video post instead.',
  ].join('\n'),

  UNSUPPORTED_URL: [
    'That Instagram link is not a Reel or video post, so there is nothing for me to transcribe.',
    '',
    'Send me a link like this:',
    'https://www.instagram.com/reel/XXXXXXXXXXX/',
  ].join('\n'),

  LOGIN_REQUIRED: [
    'Instagram is asking for a login before it will serve this Reel to me.',
    '',
    'This is usually temporary. Try again in a few minutes, or send me another Reel.',
  ].join('\n'),

  PRIVATE_CONTENT: [
    'This Reel is private, deleted, or otherwise not publicly viewable, so I cannot read it.',
    '',
    'Please send me a Reel that opens normally in a logged-out browser.',
  ].join('\n'),

  MEDIA_NOT_FOUND: [
    'I could not find any video or audio to work from on this post.',
    '',
    'That usually means it is an image-only post, it has been removed, or it is region or age restricted. Try another Reel.',
  ].join('\n'),

  NO_SPEECH: [
    'I got the video but could not detect any speech in it.',
    '',
    'That happens with music-only, silent, or heavily overlaid clips. Try a Reel where someone is talking.',
  ].join('\n'),

  TRANSCRIPTION_FAILED: [
    'The transcription step did not complete for this one.',
    '',
    'Try sending the same Reel again in a minute — it is usually a temporary problem.',
  ].join('\n'),

  EMPTY_TRANSCRIPT: [
    'The transcription came back empty for this Reel.',
    '',
    'Try another Reel, or send the same one again later.',
  ].join('\n'),

  TRANSCRIPT_TOO_SHORT: [
    'There is not enough spoken content in this Reel to analyse.',
    '',
    'If that surprises you, try another Reel. Very short or silent clips do not give me anything to work with.',
  ].join('\n'),

  ACTOR_TIMEOUT: [
    'This one is taking longer than usual. The extraction is still running on my side, so I have not started a second one — I did not want to charge you twice.',
    '',
    'Try the same link again in a minute or two.',
  ].join('\n'),

  ACTOR_ERROR: [
    'Something went wrong while extracting this Reel.',
    '',
    'Try again in a minute, or send me another Reel.',
  ].join('\n'),

  EMPTY_RESULT: [
    'I did not get anything back for this link.',
    '',
    'Please check the link opens correctly, then try again.',
  ].join('\n'),

  AI_FAILED: [
    'The analysis step did not come through cleanly.',
    '',
    'Try the same Reel again in a minute — it is usually temporary. If it keeps happening, try a different Reel.',
  ].join('\n'),
};

// ---------- 3. Analysis body formatting ----------
function buildAnalysis(a) {
  const L = [];

  L.push('🎬 REEL ANALYSIS');
  L.push('');
  L.push(`Creator: @${clean(meta.creatorHandle) || 'unknown'}${meta.creatorVerified ? ' ✅' : ''}`);
  L.push(`URL: ${meta.normalizedUrl}`);
  if (typeof meta.durationSeconds === 'number') {
    const bits = [`${Math.round(meta.durationSeconds)}s`];
    const likes = compactNum(meta.likeCount);
    const comments = compactNum(meta.commentCount);
    if (likes) bits.push(`${likes} likes`);
    if (comments) bits.push(`${comments} comments`);
    L.push(`Length: ${bits.join(' · ')}`);
  }
  if (meta.language) L.push(`Language: ${clean(meta.language)}`);

  L.push('');
  L.push('💡 WHAT IT IS ABOUT');
  L.push(none(a.summary) || 'The transcript was too short to say anything reliable.');

  const hook = none(a.opening_hook);
  L.push('');
  L.push('🎣 HOOK');
  if (hook) {
    L.push(hook);
    const ht = none(a.hook_type);
    if (ht) L.push(`Type: ${ht}`);
  } else {
    L.push('No clear hook in the first seconds.');
  }

  L.push('');
  L.push('🧠 WHY IT WORKS');
  L.push(none(a.why_it_works) || 'Not enough material to judge.');
  if (none(a.content_angle)) L.push(`Angle: ${clean(a.content_angle)}`);
  if (none(a.content_structure)) L.push(`Structure: ${clean(a.content_structure)}`);

  const aud = none(a.target_audience);
  const desire = none(a.problem_desire);
  L.push('');
  L.push('🎯 TARGET AUDIENCE');
  L.push(aud || 'Not stated in the Reel.');
  if (desire) L.push(`They are after: ${desire}`);

  L.push('');
  L.push('📣 KEY MESSAGE & CTA');
  L.push(none(a.key_message) || '—');
  const emo = none(a.emotional_trigger);
  if (emo) L.push(`Emotional trigger: ${emo}`);
  L.push(`CTA: ${none(a.cta) || 'none'}`);

  L.push('');
  L.push('✍️ 3 ORIGINAL HOOKS');
  const hooks = [a.original_hook_1, a.original_hook_2, a.original_hook_3].map(none).filter(Boolean);
  if (hooks.length) hooks.forEach((h, i) => L.push(`${i + 1}. ${h}`));
  else L.push('1. —');

  L.push('');
  L.push('💭 3 CONTENT IDEAS');
  const ideas = [a.content_idea_1, a.content_idea_2, a.content_idea_3].map(none).filter(Boolean);
  if (ideas.length) ideas.forEach((t, i) => L.push(`${i + 1}. ${t}`));
  else L.push('1. —');

  L.push('');
  L.push('🎥 NEW REEL SCRIPT');
  L.push(`Hook: ${none(a.new_script_hook) || '—'}`);
  L.push('');
  L.push('Body:');
  L.push(none(a.new_script_body) || '—');
  L.push('');
  L.push(`CTA: ${none(a.new_script_cta) || '—'}`);

  const extras = [];
  if (meta.extraUrlCount > 0) {
    extras.push(`That message had ${meta.extraUrlCount + 1} links in it — I only worked on the first one.`);
  }
  if (extras.length) {
    L.push('');
    L.push(extras.join('\n'));
  }

  return L.join('\n');
}

// ---------- 4. Chunking ----------
// Telegram's per-message limit is 4096 characters. AI output easily exceeds it,
// and without chunking the whole send fails and the user receives nothing.
const SECTION_SPLIT = /(?=^(?:🎬|💡|🎣|🧠|🎯|📣|✍️|💭|🎥))/gm;

function hardSplit(s, limit) {
  const out = [];
  let rest = s;
  while (rest.length > limit) {
    let cut = rest.lastIndexOf(' ', limit);
    if (cut < limit * 0.5) cut = limit;
    out.push(rest.slice(0, cut).trimEnd());
    rest = rest.slice(cut).trimStart();
  }
  if (rest) out.push(rest);
  return out;
}

function toBlocks(text) {
  const sections = text.split(SECTION_SPLIT).filter((s) => s.trim() !== '');
  const blocks = [];
  for (const section of sections) {
    if (section.length <= CHUNK_LIMIT) {
      blocks.push(section);
      continue;
    }
    for (const para of section.split(/\n{2,}/).filter((p) => p.trim() !== '')) {
      if (para.length <= CHUNK_LIMIT) {
        blocks.push(para);
        continue;
      }
      for (const line of para.split('\n')) {
        if (line.length <= CHUNK_LIMIT) blocks.push(line);
        else blocks.push(...hardSplit(line, CHUNK_LIMIT));
      }
    }
  }
  return blocks;
}

function chunk(text) {
  if (text.length <= CHUNK_LIMIT) return [text];
  const chunks = [];
  let buf = '';
  for (const b of toBlocks(text)) {
    if (!buf) {
      buf = b;
    } else if (buf.length + 2 + b.length <= CHUNK_LIMIT) {
      buf += '\n\n' + b;
    } else {
      chunks.push(buf);
      buf = b;
    }
  }
  if (buf) chunks.push(buf);
  return chunks;
}

// ---------- 5. Assembly ----------
let body = null;
let isCached = false;

if (base.route === 'help') {
  body = HELP_TEXT;
} else if (inData.failureCode) {
  let key = inData.failureCode;
  if (key === 'UNSUPPORTED_URL') {
    key =
      inData.unsupportedReason === 'story'
        ? 'UNSUPPORTED_URL_STORY'
        : inData.unsupportedReason === 'profile'
        ? 'UNSUPPORTED_URL_PROFILE'
        : 'UNSUPPORTED_URL';
  }
  body = ERROR_MESSAGES[key] || ERROR_MESSAGES.ACTOR_ERROR;
} else if (inData.cacheHit && inData.cached) {
  isCached = true;
  const c = inData.cached;
  body =
    c.formatted ||
    `Cached result for ${c.url}\n\n(cache did not store the formatted text — please re-run without cache, or ignore this message)`;
  body +=
    '\n\n♻️ I analysed this Reel within the last 24 hours, so I reused that result instead of paying for the extraction again. Send it again after tomorrow if you want a fresh take.';
} else if (inData.summary) {
  body = buildAnalysis(inData);
} else {
  body = ERROR_MESSAGES.AI_FAILED;
}

// Optional: append the raw transcript. Off by default because one Reel analysis is already long on a phone.
// On a cache hit the raw text is unavailable (the cache does not store transcripts to save space), so this is skipped automatically.
if (
  SEND_TRANSCRIPT &&
  body &&
  !isCached &&
  !inData.failureCode &&
  base.route !== 'help' &&
  meta.transcriptText
) {
  let t = meta.transcriptText;
  let suffix = '';
  if (t.length > MAX_TRANSCRIPT_CHARS) {
    t = t.slice(0, MAX_TRANSCRIPT_CHARS);
    suffix = '\n\n…(transcript truncated)';
  }
  body += '\n\n— TRANSCRIPT —\n' + t + suffix;
}

body = stripBrackets(body);

const pieces = chunk(body).map((text, i, arr) =>
  arr.length > 1 ? `(${i + 1}/${arr.length})\n${text}` : text,
);

// ⚠️ This must output one item per chunk.
// Node 18 is the Telegram send node: an n8n send node sends one message per item,
// and its Text field is {{ $json.chunk }} (singular).
// It was once written wrongly as "one item holding a chunks array", so $json.chunk was undefined,
// Telegram received empty text → Bad Request: message text is empty.
const shared = {
  chatId: base.chatId,
  messageId: base.messageId,
  route: base.route,
  analysisMode: base.analysisMode,
  // cacheKey / normalizedUrl come from node 04 (passed down through 06/12) and are not in node 02's output
  normalizedUrl: meta.normalizedUrl ?? null,
  cacheKey: meta.cacheKey ?? null,
  fromCache: isCached,
  hasError: Boolean(inData.failureCode),
  failureCode: inData.failureCode ?? null,
  messageBody: body,
// Raw structured result, left for node 19 to write to the cache
      analysis: inData.summary ? stripOutput(inData) : null,
  chunkCount: pieces.length,
  chunks: pieces,
};

return pieces.map((text, i) => ({
  json: {
    ...shared,
    chunkIndex: i + 1,
    chunk: text,
  },
}));

// 19 — Save To Cache
// On success, write the result back to static storage so the next request for the same Reel can reuse it.
// Neither failures nor cache hits are written.

// ===== Tunable parameters (kept in sync with node 06) =====
const CACHE_TTL_MS = 24 * 60 * 60 * 1000;
const MAX_ENTRIES = 15;
const MAX_BYTES = 40000;
// ===========================================

// ⚠️ Do **not** use $input.first().json as the business data here.
// Node 18 is the Telegram send node, so its output is the Telegram API response
// ({ ok: true, result: {...} }), not the data from node 17 —
// reading it directly gives an object without cacheKey / hasError / route,
// so the cache is never written (measured: cacheWritten stays false,
// and sending the same Reel again pays for Apify a second time).
// The correct approach: go back and take the output of node 17.
const sent = $input.first().json;                       // the Telegram API response, used only to record whether it was sent
const d = $('17 — Format Creator Insights').first().json; // the real business data (node 17 splits into multiple chunks, so just take the first)

// Node 12 only runs on the path where a transcript was actually obtained.
// It does not run on the help / early-rejection (NO_URL, non-Reel link) / extraction-failure paths,
// where $('12 — Validate Transcript') throws and marks the node red.
// Nothing should be cached on those paths anyway, so a try wrap is enough.
let upstream = {};
try {
  upstream = $('12 — Validate Transcript').first().json;
} catch {
  upstream = {};
}

if (d.hasError || d.route === 'help' || !d.cacheKey || !upstream.transcriptUsable) {
  return [{ json: { ...d, telegramSent: sent?.ok ?? null, cacheWritten: false } }];
}

const store = $getWorkflowStaticData('global');
if (!store.reelCache || typeof store.reelCache !== 'object') store.reelCache = {};

store.reelCache[d.cacheKey] = {
  key: d.cacheKey,
  reelId: upstream.reelId,
  url: d.normalizedUrl,
  creator: upstream.creatorHandle,
  durationSeconds: upstream.durationSeconds,
  language: upstream.language,
  createdAt: Date.now(),
  // Store only the analysis and the formatted body, not the raw transcript:
  // one transcript can be thousands of characters, and 15 of them blow the size budget,
  // crowding out the valuable analysis. V1 does not send the transcript by default either, so functionality is unaffected.
  analysis: d.analysis ?? null,
  formatted: d.messageBody,
};

// ---- Eviction: by entry count first, then by size — two safeguards ----
const keys = Object.keys(store.reelCache).sort(
  (a, b) => (store.reelCache[a].createdAt || 0) - (store.reelCache[b].createdAt || 0),
);
while (keys.length > MAX_ENTRIES) {
  delete store.reelCache[keys.shift()];
}
keys.sort((a, b) => (store.reelCache[a].createdAt || 0) - (store.reelCache[b].createdAt || 0));
let cacheBytes = JSON.stringify(store.reelCache).length;
while (cacheBytes > MAX_BYTES && keys.length > 1) {
  delete store.reelCache[keys.shift()];
  cacheBytes = JSON.stringify(store.reelCache).length;
}

return [
  {
    json: {
      ...d,
      telegramSent: sent?.ok ?? null,
      cacheWritten: true,
      cacheEntryCount: Object.keys(store.reelCache).length,
      cacheBytes,
    },
  },
];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "summary": {
      "type": "string",
      "description": "2-3 sentence neutral summary of what this Reel is about."
    },
    "opening_hook": {
      "type": "string",
      "description": "The first 1-2 lines spoken or shown. Reproduce verbatim if possible, otherwise summarise. If there is no hook, write NONE."
    },
    "hook_type": {
      "type": "string",
      "description": "One of: Question / Bold claim / Contrarian / Story / List / Tutorial / Problem-agitation / Social proof / Curiosity gap / Other."
    },
    "core_topic": {
      "type": "string",
      "description": "The single main subject of the Reel, 3-8 words."
    },
    "content_angle": {
      "type": "string",
      "description": "The specific angle or lens the creator uses on that topic. One sentence."
    },
    "target_audience": {
      "type": "string",
      "description": "Who this is made for. Be specific about role, stage or situation. Do not write 'everyone'. 1-2 sentences."
    },
    "problem_desire": {
      "type": "string",
      "description": "The problem it solves or the desire it speaks to. 1-2 sentences."
    },
    "key_message": {
      "type": "string",
      "description": "The one thing a viewer should walk away knowing. One sentence."
    },
    "cta": {
      "type": "string",
      "description": "The call to action, as close to verbatim as possible. Write NONE if there is none."
    },
    "emotional_trigger": {
      "type": "string",
      "description": "One of: Fear / Hope / Curiosity / Belonging / Envy / Relief / Anger / Pride / Urgency / Entertainment."
    },
    "content_structure": {
      "type": "string",
      "description": "Step-by-step structure, for example Hook -> Problem -> 3 tips -> CTA. Under 40 words."
    },
    "why_it_works": {
      "type": "string",
      "description": "2-4 sentences on the mechanics of why this holds attention and persuades. Explain, do not flatter."
    },
    "original_hook_1": {
      "type": "string",
      "description": "Original hook 1 for the same underlying idea. Must be genuinely original wording, not the source with words swapped."
    },
    "original_hook_2": {
      "type": "string",
      "description": "Original hook 2."
    },
    "original_hook_3": {
      "type": "string",
      "description": "Original hook 3."
    },
    "content_idea_1": {
      "type": "string",
      "description": "Adjacent content idea 1. A different angle or scenario built on the same underlying insight."
    },
    "content_idea_2": {
      "type": "string",
      "description": "Adjacent content idea 2."
    },
    "content_idea_3": {
      "type": "string",
      "description": "Adjacent content idea 3."
    },
    "new_script_hook": {
      "type": "string",
      "description": "Opening hook for an original Reel script. 1-2 lines, speakable out loud."
    },
    "new_script_body": {
      "type": "string",
      "description": "Body of an original Reel script. 60-110 words, conversational, short sentences."
    },
    "new_script_cta": {
      "type": "string",
      "description": "Closing call to action for that script. One sentence."
    },
    "language": {
      "type": "string",
      "description": "Language code of the transcript you analysed, for example en, es, zh-CN."
    }
  },
  "required": [
    "content_idea_2",
    "key_message",
    "emotional_trigger",
    "content_angle",
    "target_audience",
    "core_topic",
    "summary",
    "original_hook_1",
    "problem_desire",
    "content_idea_1",
    "new_script_body",
    "hook_type",
    "cta",
    "why_it_works",
    "content_structure",
    "language",
    "opening_hook",
    "original_hook_3",
    "content_idea_3",
    "new_script_hook",
    "new_script_cta",
    "original_hook_2"
  ]
}
